package com.facelessshorts.api.service.tools;
import com.facelessshorts.api.service.ToolService;
import com.facelessshorts.api.service.infrastructure.*;
import com.facelessshorts.api.service.integration.*;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.*; import com.facelessshorts.api.error.ApiException; import java.io.*; import java.nio.file.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class GenSfxService {
 private final ToolSupport support; private final ElevenLabsHttpClient eleven; public GenSfxService(ToolSupport s,ElevenLabsHttpClient e){support=s;eleven=e;}
 public Map<String,Object> run(Path project,List<String>a,String fn){ObjectMapper j=support.json();Path d=project.resolve("sfx"), pal=d.resolve("palette.json"),catp=d.resolve("catalog.json");try{JsonNode root=j.readTree(Files.readString(pal));ObjectNode cat=Files.exists(catp)?(ObjectNode)j.readTree(Files.readString(catp)):j.createObjectNode();ArrayNode clips=cat.withArray("clips");Map<String,ObjectNode> old=new LinkedHashMap<>();clips.forEach(n->old.put(n.path("id").asText(),(ObjectNode)n));Files.createDirectories(d.resolve("clips"));Set<String> only=only(a);boolean force=a.contains("--force"),dry=a.contains("--dry-run");List<String> generated=new ArrayList<>(),skipped=new ArrayList<>();JsonNode def=root.path("defaults");for(JsonNode s:root.path("sounds")){String id=s.path("id").asText();if(only!=null&&!only.contains(id))continue;String rel="clips/"+id+".mp3";Path out=d.resolve(rel);if(Files.exists(out)&&!force){skipped.add(id);continue;}if(dry){generated.add(id);continue;}Files.write(out,eleven.sfx(s.path("prompt").asText(),s.path("duration_s").asDouble(1),def.path("prompt_influence").asDouble(.45),def.path("model").asText("eleven_text_to_sound_v2")));ObjectNode e=old.getOrDefault(id,j.createObjectNode());e.put("id",id);e.put("file",rel);e.set("tags",s.path("tags"));e.put("prompt",s.path("prompt").asText());e.put("source","elevenlabs:sound-generation");old.put(id,e);generated.add(id);}clips.removeAll();old.values().forEach(clips::add);if(!dry)Files.writeString(catp,j.writerWithDefaultPrettyPrinter().writeValueAsString(cat)+"\n");return ToolService.envelope("gen_sfx",fn,Map.of("generated",generated,"skipped",skipped,"dry_run",dry));}catch(IOException e){throw new ApiException(500,"Cannot process SFX palette",e);}}
 private Set<String>only(List<String>a){int i=a.indexOf("--only");return i<0||i+1>=a.size()?null:new HashSet<>(Arrays.asList(a.get(i+1).split(",")));}
}